<template><el-dialog title="备件TOC权重与DOE过程" :visible="!!material" @close="$emit('close')" append-to-body width="94%" top="3vh"><div v-loading="loading"><h3>{{material}}</h3><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="row"><h3>{{row.material_name}}</h3><el-alert v-if="row.is_demo" title="当前为演示备件。权重系数与DOE响应含模拟数据，不代表真实试验验证通过。" type="warning" :closable="false"/><p>分类：{{row.classification.abc}} / {{row.classification.ved}} / {{row.classification.fsn}}；本备件TOC采购优先权重系数：{{row.weight===null?'数据不足':row.weight+'%'}}；历史单位TOC：{{row.unit_toc===null?'数据不足':row.unit_toc}} {{data.currency}}；有效成本批次：{{row.batch_ids.length}}</p><el-alert title="这里的TOC结果是采购优先权重系数，不是建议采购数量。采购数量须结合实际需求、库存、在途与安全储备另行确认。" type="info" :closable="false"/></template><DoeAnalysis v-if="material" :key="material" :material="material" fingerprint="spare-classification-doe-v2" response-label="采购优先权重响应" design-kind="three_level" :default-runs="30" :default-factors="doeFactors"/></div></el-dialog></template>
<script>
import {api} from '../api/client';import DoeAnalysis from './DoeAnalysis.vue';
export default {components:{DoeAnalysis},props:{material:String},data:()=>({data:{},row:null,loading:false,error:'',requestId:0,doeFactors:[{name:'ABC价值等级（C=1/B=2/A=3）',low:1,high:3},{name:'VED关键性等级（D=1/E=2/V=3）',low:1,high:3},{name:'FSN流动性等级（N=1/S=2/F=3）',low:1,high:3}]}),watch:{material:{immediate:true,handler(v){if(v)this.load(v);else this.requestId++;}}},methods:{async load(code){const id=++this.requestId;this.loading=true;this.error='';this.row=null;try{const data=(await api.get('/spare-plans/ranking')).data;if(id!==this.requestId)return;this.data=data;this.row=data.items.find(r=>r.material_code===code)||null;if(!this.row)this.error='该备件暂无可用权重数据，DOE记录仍可查看。';}catch(e){if(id===this.requestId)this.error=e.response?.data?.detail||'分析加载失败';}finally{if(id===this.requestId)this.loading=false;}}}};
</script>
